-- Seed Datasets
INSERT INTO data_sets (id, name, slug, description, icon, schema, display_config, policy_json)
VALUES
  (
    '11111111-1111-1111-1111-111111111111',
    'Blog Posts',
    'posts',
    'Content-focused blog posts with SEO support',
    '📝',
    '[
      {"fieldName":"title","fieldType":"text","required":true},
      {"fieldName":"slug","fieldType":"text","required":true},
      {"fieldName":"excerpt","fieldType":"text"},
      {"fieldName":"content","fieldType":"richtext","required":true},
      {"fieldName":"coverImage","fieldType":"image"},
      {"fieldName":"published","fieldType":"boolean","defaultValue":"false"},
      {"fieldName":"publishedAt","fieldType":"date"},
      {"fieldName":"tags","fieldType":"relation"}
    ]'::jsonb,
    '{"titleField":"title","sortField":"publishedAt","sortDirection":"desc"}'::jsonb,
    '{"readAccess":"authenticated","writeAccess":"authenticated","enableRLS":true,"rlsRules":[{"field":"ownerId","operator":"eq","value":"{{current_user_id}}"}]}'::jsonb
  ),
  (
    '11111111-1111-1111-1111-111111111112',
    'Tags',
    'tags',
    'Taxonomy tags for blog posts',
    '🏷️',
    '[
      {"fieldName":"name","fieldType":"text","required":true},
      {"fieldName":"slug","fieldType":"text","required":true}
    ]'::jsonb,
    '{"titleField":"name","sortField":"name","sortDirection":"asc"}'::jsonb,
    '{"readAccess":"authenticated","writeAccess":"authenticated","enableRLS":true,"rlsRules":[{"field":"ownerId","operator":"eq","value":"{{current_user_id}}"}]}'::jsonb
  )
